input.sparql:
SELECT ?point ?class ?ts WHERE {
  ?point a ?class .
  ?point ref:hasTimeseriesId ?ts .
  FILTER (FILTER (contains(str(?class), "Electric")) || FILTER (contains(str(?class), "Electricity")))
}

SELECT ?point ?class ?ts WHERE {
  ?point a/a brick:Building_Electrical_Meter .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point a ?class . }
}
